import java.util.*;
public class IrregularIslandTest{public static void main(String[]args){var g=new TerrainGraph();var c=g.add(TerrainGraph.Type.CONSTANT,0,0);c.values.put("height",110.0);var island=g.add(TerrainGraph.Type.ISLAND,0,0);island.input[0]=c.id;island.values.put("depth",180.0);island.values.put("radius",1.2);var oval=g.evaluate(256,16384,62,20261016,island.id,()->false).output();island.values.put("shoreVariation",.55);var coast=g.evaluate(256,16384,62,20261016,island.id,()->false).output();if(Arrays.equals(oval,coast))throw new AssertionError("Shape did not change");for(int x=0;x<256;x++)if(coast[x]>62||coast[255*256+x]>62||coast[x*256]>62||coast[x*256+255]>62)throw new AssertionError("Map edge not ocean");if(coast[128*256+128]<=62)throw new AssertionError("Lost island center");System.out.println("PASS: changed irregular coastline, ocean boundaries and dry center");}}
